def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z]+[1-9][0-9]?|[A-Z]+|<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse(formula):
        tokens = token_pattern.findall(formula)
        output = []
        operators = []
        expecting_operand = True
        i = 0

        def apply_operator(op):
            if op == "neg":
                output.append(("neg", output.pop()))
            else:
                right = output.pop()
                left = output.pop()
                if op == ":":
                    output.append(("range", left[1], right[1]))
                else:
                    output.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                output.append(("number", int(token)))
                expecting_operand = False
            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == "(":
                    operators.append(("function", token))
                    expecting_operand = True
                else:
                    output.append(("reference", token))
                    expecting_operand = False
            elif token == "(":
                operators.append(["(", 0])
                expecting_operand = True
            elif token == ",":
                while operators[-1][0] != "(":
                    apply_operator(operators.pop()[1])
                operators[-1][1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1][0] != "(":
                    apply_operator(operators.pop()[1])
                count = operators.pop()[1] + 1
                if operators and operators[-1][0] == "function":
                    name = operators.pop()[1]
                    args = output[-count:]
                    del output[-count:]
                    output.append(("function", name, args))
                expecting_operand = False
            else:
                op = "neg" if token == "-" and expecting_operand else token
                while operators and operators[-1][0] == "operator":
                    top = operators[-1][1]
                    if precedence[top] > precedence[op] or (
                        precedence[top] == precedence[op] and op != "neg"
                    ):
                        apply_operator(operators.pop()[1])
                    else:
                        break
                operators.append(("operator", op))
                expecting_operand = True
            i += 1

        while operators:
            apply_operator(operators.pop()[1])
        return output[0]

    def function_arguments(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, second = arg[1], arg[2]
            col_start = min(ord(first[0]), ord(second[0]))
            col_end = max(ord(first[0]), ord(second[0]))
            row_start = min(int(first[1:]), int(second[1:]))
            row_end = max(int(first[1:]), int(second[1:]))

            for row in range(row_start, row_end + 1):
                for col in range(col_start, col_end + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("reference", name)

    values = {}
    active = set()

    def evaluate_cell(start):
        tasks = [("cell", start)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    results.append(0)
                elif name in values:
                    results.append(values[name])
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    tasks.append(("finish_cell", name))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(int(content))

            elif kind == "finish_cell":
                name = task[1]
                values[name] = results[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("finish_neg",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node[1] == "IF":
                    tasks.append(("if_condition", node[2][1], node[2][2]))
                    tasks.append(("eval", node[2][0]))
                else:
                    tasks.append(
                        ("function_next", node[1], function_arguments(node[2]), None)
                    )

            elif kind == "finish_neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if_condition":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "function_next":
                name, args, aggregate = task[1], task[2], task[3]
                try:
                    arg = next(args)
                except StopIteration:
                    results.append(0 if aggregate is None else aggregate)
                else:
                    tasks.append(("function_value", name, args, aggregate))
                    tasks.append(("eval", arg))

            elif kind == "function_value":
                name, args, aggregate = task[1], task[2], task[3]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if aggregate is None:
                        aggregate = value
                    elif name == "SUM":
                        aggregate += value
                    elif name == "MIN":
                        aggregate = min(aggregate, value)
                    else:
                        aggregate = max(aggregate, value)
                    tasks.append(("function_next", name, args, aggregate))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate_cell(name)

    return {name: values[name] for name in cells}
